func (this *MenuItem) UpdateAccelerator(accelGroup int64, add bool) {
	if this.accelerator == 0 || !this.GetEnabled() {
		return
	}
	if (this.accelerator & COMMAND) != 0 {
		return
	}
	var mask int32 = 0
	if (this.accelerator & ALT) != 0 {
		mask |= gtk.GDKGDK_MOD1_MASK
	}
	if (this.accelerator & SHIFT) != 0 {
		mask |= gtk.GDKGDK_SHIFT_MASK
	}
	if (this.accelerator & CONTROL) != 0 {
		mask |= gtk.GDKGDK_CONTROL_MASK
	}
	var keysym int32 = this.accelerator & KEY_MASK
	var newKey int32 = DisplayUntranslateKey(keysym)
	if newKey != 0 {
		keysym = newKey
	} else {
		switch keysym {
		case int32('\u000d'):
			keysym = gtk.GDKGDK_Return
			break
		default:
			keysym = int32(gtk.ConverterWcsToMbcsCh(uint16(keysym)))
		}
	}
	if keysym != 0 {
		if add {
			gtk.GTK3Gtk_widget_add_accelerator(this.Handle, gtk.OSActivate, accelGroup, keysym, mask, gtk.GTKGTK_ACCEL_VISIBLE)
		} else {
			gtk.GTK3Gtk_widget_remove_accelerator(this.Handle, accelGroup, keysym, mask)
		}
	}
}

func (this *MenuItem) GetMaskKeysym() *MenuItem_MaskKeysym {
	if this.text == "" {
		return nil
	}
	var maskKeysym *MenuItem_MaskKeysym = newMenuItemMaskKeysym()
	var accelIndex int32 = jrt.IndexFrom(this.text, string(rune('\u0009')), 0)
	if accelIndex == -1 {
		return nil
	}
	var start int32 = accelIndex + 1
	for {
		var plusIndex int32 = jrt.IndexFrom(this.text, string(rune('+')), start)
		if plusIndex < 0 || plusIndex == jrt.StringLength(this.text)-1 {
			break
		}
		var maskStr string = jrt.Substring(this.text, start, plusIndex)
		if maskStr == "Ctrl" {
			maskKeysym.mask |= gtk.GDKGDK_CONTROL_MASK
		}
		if maskStr == "Shift" {
			maskKeysym.mask |= gtk.GDKGDK_SHIFT_MASK
		}
		if maskStr == "Alt" {
			maskKeysym.mask |= gtk.GDKGDK_MOD1_MASK
		}
		start = plusIndex + 1
	}
	var word string = jrt.Substring(this.text, start, -1)
	switch word {
	case "Del", "Delete":
		maskKeysym.keysym = gtk.GDKGDK_Delete
	case "Enter":
		maskKeysym.keysym = gtk.GDKGDK_ISO_Enter
	case "Ins", "Insert":
		maskKeysym.keysym = gtk.GDKGDK_Insert
	case "Ret", "Return":
		maskKeysym.keysym = gtk.GDKGDK_Return
	case "Up":
		maskKeysym.keysym = gtk.GDKGDK_Up
	case "Down":
		maskKeysym.keysym = gtk.GDKGDK_Down
	case "Right":
		maskKeysym.keysym = gtk.GDKGDK_Right
	case "Left":
		maskKeysym.keysym = gtk.GDKGDK_Left
	case "Page Up":
		maskKeysym.keysym = gtk.GDKGDK_Page_Up
	case "Page Down":
		maskKeysym.keysym = gtk.GDKGDK_Page_Down
	case "Keypad +", "Numpad +":
		maskKeysym.keysym = gtk.GDKGDK_KP_Add
	case "Keypad -", "Numpad -":
		maskKeysym.keysym = gtk.GDKGDK_KP_Subtract
	case "Keypad *", "Numpad *":
		maskKeysym.keysym = gtk.GDKGDK_KP_Multiply
	case "Keypad /", "Numpad /":
		maskKeysym.keysym = gtk.GDKGDK_KP_Divide
	case "ESC", "Escape":
		maskKeysym.keysym = gtk.GDKGDK_Escape
	case "Backspace":
		maskKeysym.keysym = gtk.GDKGDK_BackSpace
	case "Home":
		maskKeysym.keysym = gtk.GDKGDK_Home
	case "End":
		maskKeysym.keysym = gtk.GDKGDK_End
	case "Tab":
		maskKeysym.keysym = gtk.GDKGDK_Tab
	case "Space":
		maskKeysym.keysym = gtk.GDKGDK_space
	case "F1":
		maskKeysym.keysym = gtk.GDKGDK_F1
	case "F2":
		maskKeysym.keysym = gtk.GDKGDK_F2
	case "F3":
		maskKeysym.keysym = gtk.GDKGDK_F3
	case "F4":
		maskKeysym.keysym = gtk.GDKGDK_F4
	case "F5":
		maskKeysym.keysym = gtk.GDKGDK_F5
	case "F6":
		maskKeysym.keysym = gtk.GDKGDK_F6
	case "F7":
		maskKeysym.keysym = gtk.GDKGDK_F7
	case "F8":
		maskKeysym.keysym = gtk.GDKGDK_F8
	case "F9":
		maskKeysym.keysym = gtk.GDKGDK_F9
	case "F10":
		maskKeysym.keysym = gtk.GDKGDK_F10
	case "F11":
		maskKeysym.keysym = gtk.GDKGDK_F11
	case "F12":
		maskKeysym.keysym = gtk.GDKGDK_F12
	case "F13":
		maskKeysym.keysym = gtk.GDKGDK_F13
	case "F14":
		maskKeysym.keysym = gtk.GDKGDK_F14
	case "F15":
		maskKeysym.keysym = gtk.GDKGDK_F15
	default:
		{
			if jrt.StringLength(word) == 1 {
				maskKeysym.keysym = int32(gtk.ConverterWcsToMbcsCh(utf16.Encode([]rune(word))[0]))
			}
		}
	}
	return maskKeysym
}

func (this *MenuItem) UpdateAcceleratorText(show bool) bool {
	if this.accelerator != 0 {
		return false
	}
	var maskKeysym *MenuItem_MaskKeysym = nil
	if show {
		maskKeysym = this.GetMaskKeysym()
	}
	if maskKeysym == (nil) {
		return true
	}
	if maskKeysym.keysym != 0 {
		var accelGroup int64 = this.GetAccelGroup()
		if show {
			gtk.GTK3Gtk_widget_add_accelerator(this.Handle, gtk.OSActivate, accelGroup, maskKeysym.keysym, maskKeysym.mask, gtk.GTKGTK_ACCEL_VISIBLE)
		} else {
			gtk.GTK3Gtk_widget_remove_accelerator(this.Handle, accelGroup, maskKeysym.keysym, maskKeysym.mask)
		}
	}
	return maskKeysym.keysym != 0
}

